
#include "motor.h"
#include "robot_config.h"
#include "main.h"

/* TIM3 handle generated by CubeMX */
extern TIM_HandleTypeDef htim3;

/* ================= PIN CONFIGURATION ================= */

/* TB6612FNG STBY */
#define MOTOR_STBY_PORT       GPIOA
#define MOTOR_STBY_PIN        GPIO_PIN_5

/* Motor A - Left */
#define MOTOR_A_IN1_PORT      GPIOB
#define MOTOR_A_IN1_PIN       GPIO_PIN_12

#define MOTOR_A_IN2_PORT      GPIOB
#define MOTOR_A_IN2_PIN       GPIO_PIN_13

#define MOTOR_A_PWM_CHANNEL   TIM_CHANNEL_1

/* Motor B - Right */
#define MOTOR_B_IN1_PORT      GPIOB
#define MOTOR_B_IN1_PIN       GPIO_PIN_14

#define MOTOR_B_IN2_PORT      GPIOB
#define MOTOR_B_IN2_PIN       GPIO_PIN_15

#define MOTOR_B_PWM_CHANNEL   TIM_CHANNEL_2

/* PWM configuration */
#define MOTOR_PWM_MAX         3599U

/* ================= PRIVATE FUNCTIONS ================= */

static void Motor_SetDirection(
    Motor_ID_t motor,
    GPIO_PinState in1,
    GPIO_PinState in2)
{
    if (motor == MOTOR_LEFT)
    {
        HAL_GPIO_WritePin(
            MOTOR_A_IN1_PORT,
            MOTOR_A_IN1_PIN,
            in1);

        HAL_GPIO_WritePin(
            MOTOR_A_IN2_PORT,
            MOTOR_A_IN2_PIN,
            in2);
    }
    else if (motor == MOTOR_RIGHT)
    {
        HAL_GPIO_WritePin(
            MOTOR_B_IN1_PORT,
            MOTOR_B_IN1_PIN,
            in1);

        HAL_GPIO_WritePin(
            MOTOR_B_IN2_PORT,
            MOTOR_B_IN2_PIN,
            in2);
    }
}

static void Motor_SetPWM(
    Motor_ID_t motor,
    uint16_t pwm)
{
    if (motor == MOTOR_LEFT)
    {
        __HAL_TIM_SET_COMPARE(
            &htim3,
            MOTOR_A_PWM_CHANNEL,
            pwm);
    }
    else if (motor == MOTOR_RIGHT)
    {
        __HAL_TIM_SET_COMPARE(
            &htim3,
            MOTOR_B_PWM_CHANNEL,
            pwm);
    }
}

/* Chieu hien tai: 1 = tien, -1 = lui, 0 = tha troi, 2 = phanh */
static int8_t motor_dir[2] = {0, 0};

/* ================= PUBLIC FUNCTIONS ================= */

Motor_Status_t Motor_Init(void)
{
    /* Keep driver in standby during initialization */
    HAL_GPIO_WritePin(
        MOTOR_STBY_PORT,
        MOTOR_STBY_PIN,
        GPIO_PIN_RESET);

    /* Initial direction: coast */
    Motor_SetDirection(
        MOTOR_LEFT,
        GPIO_PIN_RESET,
        GPIO_PIN_RESET);

    Motor_SetDirection(
        MOTOR_RIGHT,
        GPIO_PIN_RESET,
        GPIO_PIN_RESET);

    Motor_SetPWM(MOTOR_LEFT, 0);
    Motor_SetPWM(MOTOR_RIGHT, 0);

    /* Start PWM channels */
    if (HAL_TIM_PWM_Start(
            &htim3,
            MOTOR_A_PWM_CHANNEL) != HAL_OK)
    {
        return MOTOR_ERROR;
    }

    if (HAL_TIM_PWM_Start(
            &htim3,
            MOTOR_B_PWM_CHANNEL) != HAL_OK)
    {
        HAL_TIM_PWM_Stop(
            &htim3,
            MOTOR_A_PWM_CHANNEL);

        return MOTOR_ERROR;
    }

    /* Enable TB6612FNG */
    HAL_GPIO_WritePin(
        MOTOR_STBY_PORT,
        MOTOR_STBY_PIN,
        GPIO_PIN_SET);

    return MOTOR_OK;
}

Motor_Status_t Motor_SetSpeed(
    Motor_ID_t motor,
    int16_t speed)
{
    uint16_t pwm;

    GPIO_PinState in1;
    GPIO_PinState in2;

    /* Validate motor */
    if ((motor != MOTOR_LEFT) &&
        (motor != MOTOR_RIGHT))
    {
        return MOTOR_ERROR;
    }

    /* Limit speed */
    if (speed > 100)
    {
        speed = 100;
    }
    else if (speed < -100)
    {
        speed = -100;
    }

    /* Zero speed: coast */
    if (speed == 0)
    {
        Motor_Stop(motor);
        return MOTOR_OK;
    }

    /* Calculate PWM duty */
    if (speed > 0)
    {
        in1 = GPIO_PIN_SET;
        in2 = GPIO_PIN_RESET;

        pwm = ((uint32_t)speed * MOTOR_PWM_MAX) / 100U;
    }
    else
    {
        in1 = GPIO_PIN_RESET;
        in2 = GPIO_PIN_SET;

        pwm = ((uint32_t)(-speed) * MOTOR_PWM_MAX) / 100U;
    }

    /* Avoid changing direction under active PWM */
    motor_dir[motor] = (speed > 0) ? 1 : -1;
    Motor_SetPWM(motor, 0);

    Motor_SetDirection(motor, in1, in2);

    Motor_SetPWM(motor, pwm);

    return MOTOR_OK;
}

void Motor_Stop(Motor_ID_t motor)
{
    if ((motor != MOTOR_LEFT) &&
        (motor != MOTOR_RIGHT))
    {
        return;
    }

    Motor_SetPWM(motor, 0);

    Motor_SetDirection(
        motor,
        GPIO_PIN_RESET,
        GPIO_PIN_RESET);

    motor_dir[motor] = 0;
}

void Motor_StopAll(void)
{
    Motor_Stop(MOTOR_LEFT);
    Motor_Stop(MOTOR_RIGHT);
}

void Motor_Disable(void)
{
    Motor_StopAll();

    HAL_GPIO_WritePin(
        MOTOR_STBY_PORT,
        MOTOR_STBY_PIN,
        GPIO_PIN_RESET);
}

/* ================= DIEU KHIEN PWM TRUC TIEP ================= */

Motor_Status_t Motor_SetDuty(
    Motor_ID_t motor,
    int16_t duty)
{
    int8_t dir;
    uint16_t pwm;

    if ((motor != MOTOR_LEFT) &&
        (motor != MOTOR_RIGHT))
    {
        return MOTOR_ERROR;
    }

    /* Dao chieu theo cau hinh (robot_config.h) */
    if (((motor == MOTOR_LEFT)  && (MOTOR_LEFT_REVERSE  != 0)) ||
        ((motor == MOTOR_RIGHT) && (MOTOR_RIGHT_REVERSE != 0)))
    {
        duty = (int16_t)(-duty);
    }

    if (duty > (int16_t)MOTOR_DUTY_MAX)
    {
        duty = MOTOR_DUTY_MAX;
    }
    else if (duty < -(int16_t)MOTOR_DUTY_MAX)
    {
        duty = -(int16_t)MOTOR_DUTY_MAX;
    }

    if (duty == 0)
    {
        Motor_Stop(motor);
        motor_dir[motor] = 0;
        return MOTOR_OK;
    }

    if (duty > 0)
    {
        dir = 1;
        pwm = (uint16_t)duty;
    }
    else
    {
        dir = -1;
        pwm = (uint16_t)(-duty);
    }

    /* Chi doi chieu / thoat phanh khi can: tranh nhieu GPIO moi chu ky */
    if (dir != motor_dir[motor])
    {
        Motor_SetPWM(motor, 0);

        if (dir > 0)
        {
            Motor_SetDirection(motor, GPIO_PIN_SET, GPIO_PIN_RESET);
        }
        else
        {
            Motor_SetDirection(motor, GPIO_PIN_RESET, GPIO_PIN_SET);
        }

        motor_dir[motor] = dir;
    }

    Motor_SetPWM(motor, pwm);

    return MOTOR_OK;
}

Motor_Status_t Motor_SetDutyPercent(
    Motor_ID_t motor,
    float duty_pct)
{
    if (duty_pct > 100.0f)
    {
        duty_pct = 100.0f;
    }
    else if (duty_pct < -100.0f)
    {
        duty_pct = -100.0f;
    }

    return Motor_SetDuty(
        motor,
        (int16_t)(duty_pct * ((float)MOTOR_DUTY_MAX / 100.0f)));
}

/* ================= PHANH ================= */

void Motor_Brake(Motor_ID_t motor)
{
    if ((motor != MOTOR_LEFT) &&
        (motor != MOTOR_RIGHT))
    {
        return;
    }

    if (motor_dir[motor] == 2)
    {
        return;
    }

    Motor_SetPWM(motor, MOTOR_PWM_MAX);
    Motor_SetDirection(motor, GPIO_PIN_SET, GPIO_PIN_SET);

    motor_dir[motor] = 2;
}

void Motor_BrakeAll(void)
{
    Motor_Brake(MOTOR_LEFT);
    Motor_Brake(MOTOR_RIGHT);
}
